# Embeds native/assets/coop_button.png into the DLL: writes native/src/coop_button_png.h.
# Usage (from the repository root): python tools/sprites/png2header.py
from pathlib import Path

data = Path('native/assets/coop_button.png').read_bytes()
rows = [', '.join(f'0x{b:02X}' for b in data[i:i + 16]) for i in range(0, len(data), 16)]
Path('native/src/coop_button_png.h').write_text(
    '// Generated by tools/sprites/png2header.py from native/assets/coop_button.png - do not edit.\n'
    '// The main menu COOP button: 2 frames of 98x26 side by side (with and without the word).\n'
    '#pragma once\n\n'
    'namespace coop {\n\n'
    'constexpr unsigned char kCoopButtonPng[] = {\n    ' + ',\n    '.join(rows) + ',\n};\n\n'
    '}  // namespace coop\n', newline='\n')
print(f'{len(data)} bytes')
